/* Hellfire Pulp artwork on whitened paper, multiplied into the cream cards. K = crowned, Q = veil and rose, J = helmeted soldier. Suit emblems are transparent PNGs (paper keyed out). */
CardEngine.registerAssets('hellfire-pulp', {"blend": "multiply", "faces": {"J": {"red": "data:image/jpeg;base64,", "black": "data:image/jpeg;base64,"}, "Q": {"red": "data:image/jpeg;base64,", "black": "data:image/jpeg;base64,"}, "K": {"red": "data:image/jpeg;base64,", "black": "data:image/jpeg;base64,"}}, "suits": {"S": "data:image/png;base64,", "H": "data:image/png;base64,", "C": "data:image/png;base64,", "D": "data:image/png;base64,"}, "focus": {"K": [0.62, 0.2], "Q": [0.55, 0.2], "J": [0.58, 0.27]}});
/* Lite art for small cards (and the Lite option). */
CardEngine.registerLite("hellfire-pulp", {"faces": {"K": {"red": "data:image/jpeg;base64,", "black": "data:image/jpeg;base64,"}, "Q": {"red": "data:image/jpeg;base64,", "black": "data:image/jpeg;base64,"}, "J": {"red": "data:image/jpeg;base64,", "black": "data:image/jpeg;base64,"}}, "suits": {"S": "data:image/webp;base64,", "H": "data:image/webp;base64,", "C": "data:image/webp;base64,", "D": "data:image/webp;base64,"}, "blend": "multiply", "focus": {"K": [0.5, 0.56], "Q": [0.5, 0.42], "J": [0.42, 0.48]}});
